#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";

const TITLE = "MVP Trainer V5 R9.2.2 Mobile DSP Layout Fix";
const TARGET_REL = path.join("src", "features", "music", "MusicMiniPlayer.tsx");
const BASE_SHA256 = "0bc32976ec34498a2360b8eefa49763e872e4620c2cd09e1fae52e7af8d6b7d2";
const NEW_SHA256 = "a7eb0507a27c5debc95e871fd7935d3ec53c79aa1e3b61654d7b4ccf9c67f17d";
const PAYLOAD = "";

function sha256(buffer) { return crypto.createHash("sha256").update(buffer).digest("hex"); }
function existsTarget(root) { return fs.existsSync(path.join(root, TARGET_REL)); }
function findRepoRoot() {
  const starts = [process.cwd(), path.dirname(process.argv[1] || process.cwd())];
  for (const start of starts) {
    let current = path.resolve(start);
    for (let i = 0; i < 6; i += 1) {
      if (existsTarget(current) && fs.existsSync(path.join(current, "package.json"))) return current;
      const parent = path.dirname(current);
      if (parent === current) break;
      current = parent;
    }
  }
  throw new Error("Could not find the MVPTrainerPro-Personal repo root. Put this installer in the repo scripts folder or run it from the repo.");
}

console.log(TITLE);
const root = findRepoRoot();
const target = path.join(root, TARGET_REL);
const current = fs.readFileSync(target);
const currentHash = sha256(current);
console.log(`Project: ${root}`);

if (currentHash === NEW_SHA256) {
  console.log("Already installed. No changes made.");
  process.exit(0);
}
if (currentHash !== BASE_SHA256) {
  console.error("");
  console.error("STOPPED SAFELY: MusicMiniPlayer.tsx is not the exact R9.2.0/R9.2.1 baseline expected by this fix.");
  console.error(`Current SHA256:  ${currentHash}`);
  console.error(`Expected SHA256: ${BASE_SHA256}`);
  console.error("No files were changed. Send the current deployed MusicMiniPlayer.tsx before applying another patch.");
  process.exit(2);
}

const next = zlib.gunzipSync(Buffer.from(PAYLOAD, "base64"));
if (sha256(next) !== NEW_SHA256) throw new Error("Embedded replacement integrity check failed.");
const backup = target + ".pre-r9-2-2.bak";
if (!fs.existsSync(backup)) fs.copyFileSync(target, backup);
const temp = target + ".r9-2-2.tmp";
fs.writeFileSync(temp, next);
fs.renameSync(temp, target);
if (sha256(fs.readFileSync(target)) !== NEW_SHA256) throw new Error("Post-write integrity check failed.");

console.log("Applied successfully:");
console.log("  + Mobile 31-band EQ strip forced visible with dedicated 212px scroll viewport");
console.log("  + EQ ON / Gain-Match buttons fit evenly without clipping");
console.log("  + Music Preset becomes a clean full-width mobile row");
console.log("  + Minimum / Linear Phase buttons fit cleanly");
console.log("  + Flat / Power Training and Save Custom fit full width");
console.log("  + Output controls reflow safely for phone width");
console.log("  + Immersion modes/sliders reflow safely for phone width");
console.log("  + Dynamics meters/processors reflow safely for phone width");
console.log("  + Existing DSP/audio behavior is unchanged");
console.log(`Backup: ${backup}`);
console.log("Next: cd .. && npm run build (if you ran this from scripts)");
